import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四十九卦 革 澤火革 兌上離下","description":"周易 - 第四十九卦 革 澤火革 兌上離下","frontmatter":{"title":"第四十九卦 革 澤火革 兌上離下","description":"周易 - 第四十九卦 革 澤火革 兌上離下"},"headers":[],"relativePath":"classics/zhouyi/050.md","filePath":"classics/zhouyi/050.md"}'),l={name:"classics/zhouyi/050.md"};function t(s,a,n,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="革" tabindex="-1">革 <a class="header-anchor" href="#革" aria-label="Permalink to “革”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>己日乃孚，元亨利貞，悔亡。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>革，水火相息，二女同居，其志不相得，曰革。己日乃孚；革而信也。文明以說，大亨以正，革而當，其悔乃亡。天地革而四時成，湯武革命，順乎天而應乎人，革之時 義大矣哉！ 象曰：澤中有火，革；君子以治歷明時。初九：鞏用黃牛之革。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>鞏用黃牛，不可 以有為也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>己日乃革之，徵吉，無咎。象曰：己日革之，行有嘉也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>徵兇，貞厲，革言三就，有孚。象曰：革言三就，又何之矣。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>悔亡，有孚改命，吉。象曰：改命之吉，信志也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>大人虎變，未佔有孚。象曰：大人虎變，其文炳也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>君子豹變，小人革面，徵兇，居貞吉。象曰：君子豹變，其文蔚也。小人革面，順以從君也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
